INSERT INTO `fact_job_ratio` VALUES ('2001001001','經營管理主管',34,0.0011,'負責規劃團隊的營運目標與執行方向，並協調各部門資源，幫助公司維持穩定運作並持續成長。'),('2001001002','儲備幹部',48,0.0015,'透過系統化的培訓與實務演練，培養未來的中高層管理人才，負責特定業務單元的日常運作與潛在接班人培育。'),('2001001003','主管特別助理',21,0.0007,'協助主管處理行政事務與專案協調，作為溝通各部門的橋樑，確保資訊與任務順暢傳遞與執行。'),('2001001004','副總經理',1,0.0000,'輔助最高行政長官處理公司策略與重大決策，負責跨部門資源整合與組織架構的運作效率優化。'),('2001001006','執行長',2,0.0001,'擔任公司最高決策者，負責制定企業願景與長期策略，並帶領組織實現永續發展與市場目標。'),('2001001007','營運長',1,0.0000,'監督公司核心業務流程，分析運作數據與瓶頸，提出改善方案以提升整體效率與產出品質。'),('2001002001','人力資源主管',7,0.0002,'負責人才招募、發展與留任計畫，營造良好的職場文化與員工關係，支撐組織的人力資源目標。'),('2001002002','人力資源人員',37,0.0012,'處理員工入離職、薪資福利與日常勞資事務，是員工職涯發展與公司政策溝通的重要聯絡窗口。'),('2001002003','教育訓練人員',10,0.0003,'設計與實施員工培訓課程，提升團隊技能與職場競爭力，協助員工達成個人目標與公司戰略。'),('2001002004','人力／外勞仲介',1,0.0000,'協助外國勞工辦理來台工作所需的法務與行政手續，並提供生活就業諮詢，促進雙方權益與需求的對等匹配。'),('2001002005','人力資源助理',11,0.0004,'負責協助處理員工入離職手續、薪資福利查詢與基本人事紀錄維護，是連接員工與人事系統的重要橋樑。'),('2001002006','招募顧問',1,0.0000,'負責撰寫職缺廣告、篩選求人資料並安排面試，致力於發掘適合的人才，幫助公司組建優質團隊。'),('2002001001','行政主管',7,0.0002,'規劃與協調公司行政作業流程，確保辦公環境、設備與文件運作有序，是團隊作業順暢的組織核心。'),('2002001002','總務主管',4,0.0001,'管理辦公室日常運作、採購事務與員工福利事宜，確保公司基礎設施與資源的穩定供應與維護。'),('2002001003','行政人員',182,0.0058,'處理文件整理、會議協調與辦公室常規事務，是保障公司日常運作流程順暢與資訊井井有條的關鍵角色。'),('2002001004','總務',50,0.0016,'負責辦公室物資管理、設備維護與員工服務支援，確保工作環境整潔舒適，營造良好的業務運作基礎。'),('2002001005','秘書',7,0.0002,'提供行政支援與會議記錄、行程管理服務，是幫助主管與團隊有效規劃時間與處理事務的得力助手。'),('2002001006','資料輸入人員',52,0.0017,'負責準確錄入、整理與管理各類數據與文件，確保資訊紀錄的正確性與系統的資料完整性。'),('2002001007','文件管理師',26,0.0008,'負責建立與維護文件歸檔體系，確保重要資訊易於檢索與保存，是企業知識資產管理的專業角色。'),('2002001008','圖書管理人員',3,0.0001,'管理公司或機構的圖書與資料庫，負責分類整理、借閱登記與資源推薦，促進資訊共享與學習文化的建立。'),('2002001009','總機',3,0.0001,'負責接聽來電轉接內部部門或人員，確保來訪者與公司連絡順暢，是公司首面之顔面。'),('2002001010','櫃檯接待人員',4,0.0001,'負責迎接來訪客人、處理登記手續及提供基本資訊，營造專業且友善的第一印象。'),('2002001011','實習生／工讀生',165,0.0053,'在導師指導下參與真實專案，透過實務操作學習職場流程與專業技能，是進入職場的啟門課。'),('2002001012','行政助理',162,0.0052,'負責文件歸檔、會議協調與日常事務支援，確保團隊運作流程井然有序。'),('2002002004','法務',10,0.0003,'負責公司法規遵循、合約審核與法律風險諮詢，保障業務活動在法理層面的安全性。'),('2002002005','商標／專利人員',15,0.0